def by_id():
    return {q["id"]: q for q in QUESTIONS}


#: Specialist owners a correct routing may select, for the routing classification (section 12 of the brief): by default the
#: question's own domain; cross-domain questions list the owner of each clause; ambiguous questions list every plausible owner.
SPECIALIST_OF = {"teaching": "teaching", "research": "research", "hr": "faculty_services", "institutional": "institutional"}
OWNERS = {
    "T24": ["teaching", "faculty_services"], "T33": ["teaching", "faculty_services"], "T35": ["teaching", "research"],
    "I09": ["institutional", "faculty_services"], "I40": ["institutional"], "I42": ["institutional", "faculty_services"],
    "A05": ["faculty_services", "institutional"], "A06": ["research", "institutional"], "A07": ["institutional"], "A08": ["research", "institutional"],
    "A23": ["faculty_services", "institutional"], "A31": ["institutional"], "R22": ["research", "faculty_services"], "I08": ["institutional", "research"],
    "X01": ["teaching"], "X02": ["research"], "X03": ["institutional"], "X04": ["teaching", "faculty_services"],
    "X05": ["research", "institutional"], "X06": ["faculty_services", "institutional"], "X07": ["research"], "X08": ["teaching", "institutional"],
    "X09": ["faculty_services"], "X10": ["teaching", "research"], "X11": ["research", "faculty_services"], "X12": ["research", "institutional"],
    "X13": ["teaching"], "X14": ["faculty_services"], "X15": ["institutional"], "X16": ["teaching", "faculty_services"],
    "X18": ["research", "faculty_services"], "X19": ["research", "institutional"], "X23": ["research"], "X24": ["teaching"],
    "X28": ["teaching", "institutional", "faculty_services"], "X29": ["faculty_services", "research"], "X30": ["faculty_services"],
    "X31": ["teaching", "institutional"], "X32": ["teaching"], "X34": ["teaching"], "X35": ["faculty_services"],
    "X38": ["institutional", "faculty_services"], "X39": ["institutional"], "X40": ["institutional", "research"],
}


def owners_of(entry):
    """The specialist ids a correct routing may select for this question (empty: no specialist should run)."""
    if entry["id"] in OWNERS:
        return list(OWNERS[entry["id"]])
    return [SPECIALIST_OF[entry["domain"]]] if entry["domain"] in SPECIALIST_OF else []


