    print("by expect:", dict(Counter(q["expect"] for q in QUESTIONS)))
    adv = [q for q in QUESTIONS if q["category"] == "adversarial" or any(t.startswith("adversarial:") for t in q["tags"])]
    print("adversarial:", len(adv), dict(Counter(t for q in adv for t in q["tags"] if t.startswith("adversarial:"))))
    print("regression:", sum("regression" in q["tags"] for q in QUESTIONS), " typo:", sum("typo" in q["tags"] for q in QUESTIONS),
          " paraphrase groups:", dict(Counter(t for q in QUESTIONS for t in q["tags"] if t.startswith("paraphrase:"))))
    print("known:", dict(Counter(t for q in QUESTIONS for t in q["tags"] if t.startswith("known:"))))
    missing = [i for i in DETERMINISM_IDS + LEGACY_SAMPLE_IDS + list(OWNERS) if i not in set(ids)]
    assert not missing, missing
